CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, username VARCHAR(50) NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(10) NOT NULL DEFAULT 'USER' CHECK (role IN ('USER', 'ADMIN')), status VARCHAR(10) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE users ADD COLUMN IF NOT EXISTS status VARCHAR(10) NOT NULL DEFAULT 'PENDING';
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_path TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS show_listening_activity BOOLEAN NOT NULL DEFAULT TRUE;
CREATE TABLE IF NOT EXISTS songs (id BIGSERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL, artist VARCHAR(200) NOT NULL, album VARCHAR(200) NOT NULL DEFAULT 'Unknown Album', file_path TEXT NOT NULL, cover_path TEXT, uploaded_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS playlists (id BIGSERIAL PRIMARY KEY, title VARCHAR(100) NOT NULL, user_id BIGINT NOT NULL REFERENCES users(id), is_public BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE playlists ADD COLUMN IF NOT EXISTS description VARCHAR(500);
ALTER TABLE playlists ADD COLUMN IF NOT EXISTS cover_path TEXT;
CREATE TABLE IF NOT EXISTS playlist_songs (playlist_id BIGINT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE, song_id BIGINT NOT NULL REFERENCES songs(id) ON DELETE CASCADE, added_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (playlist_id, song_id));
CREATE TABLE IF NOT EXISTS feedback (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type VARCHAR(20) NOT NULL CHECK (type IN ('SONG_REQUEST', 'FEEDBACK')), content VARCHAR(1000) NOT NULL, status VARCHAR(12) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'COMPLETED', 'REJECTED')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS chat_messages (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, message VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE chat_messages ADD COLUMN IF NOT EXISTS song_id BIGINT REFERENCES songs(id) ON DELETE SET NULL;
ALTER TABLE chat_messages ADD COLUMN IF NOT EXISTS image_path TEXT;
CREATE TABLE IF NOT EXISTS chat_message_reactions (message_id BIGINT NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, emoji VARCHAR(8) NOT NULL CHECK (emoji IN ('👍', '😆', '😮', '😢', '😡', '❤️')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (message_id, user_id, emoji));
CREATE TABLE IF NOT EXISTS direct_messages (id BIGSERIAL PRIMARY KEY, sender_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, message VARCHAR(500) NOT NULL DEFAULT '', song_id BIGINT REFERENCES songs(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (sender_id <> recipient_id), CHECK (length(trim(message)) > 0 OR song_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS follows (follower_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, following_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (follower_id, following_id), CHECK (follower_id <> following_id));
CREATE TABLE IF NOT EXISTS artist_follows (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, artist_name VARCHAR(200) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (user_id, artist_name));
CREATE TABLE IF NOT EXISTS artist_profiles (artist_name VARCHAR(200) PRIMARY KEY, image_path TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS liked_songs (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, song_id BIGINT NOT NULL REFERENCES songs(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (user_id, song_id));
CREATE TABLE IF NOT EXISTS play_history (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, song_id BIGINT NOT NULL REFERENCES songs(id) ON DELETE CASCADE, played_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS play_history_user_played_at_idx ON play_history (user_id, played_at DESC);
CREATE TABLE IF NOT EXISTS notifications (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, type VARCHAR(30) NOT NULL, message VARCHAR(300) NOT NULL, link_type VARCHAR(20), link_id TEXT, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS notifications_user_created_at_idx ON notifications (user_id, created_at DESC);
